import{z as B,x as p,o as e,c as A,q as r,j as l,D as E,d as t,s,S as i,b as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"热点与过程变化","description":"","frontmatter":{"title":"热点与过程变化","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hotspot-pv.md","filePath":"litho/hotspot-pv.md","lastUpdated":1791063341000}'),d={name:"litho/hotspot-pv.md"};function h(m,a,D,P,c,C){const o=p("Mermaid");return e(),A("div",null,[a[2]||(a[2]=r('<h1 id="热点与过程变化" tabindex="-1">热点与过程变化 <a class="header-anchor" href="#热点与过程变化" aria-label="Permalink to &quot;热点与过程变化&quot;">​</a></h1><div class="epigraph"><p>名义剂量、名义焦点上的轮廓合格，不表示剂量与焦点在规格矩形里扫一圈时仍合格。热点是过程变化下先死的那些局部图形。</p><footer>—— 据计算光刻通称：hotspot 与 PV-band；OPC 评价里的工艺窗口带</footer></div><p><a href="/litho/flare-and-stray">上一课</a>把长程散射写成全场剂量底座，对比随开孔率变。缺口是局部：同一底座上，某些二维拐角、线端、孔对 \\((E,z)\\) 与套刻的敏感远高于密线栅。本课钉设计热点与过程变化带（PV-band）。平均 CDU 被刻蚀改写成 AEI，留给<a href="/litho/cdu-etch-bias">下一课</a>；本课的对象仍是显影后轮廓在窗口里动了多少。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/opc">OPC</a> 已经要求评价不能只看中心点，而要看 PV-band：剂量与焦点在规格矩形里扫一圈，轮廓包络是否仍让出套刻与电学余量。本课把这句话从 OPC 课的评价句，收成计量课序里的失效模式。Flare 改的是缓变底座，热点是底座之上仍会先桥连、先缩断、先掉孔的那些 clips。</p><p>缺口因此是「哪些图形在过程变化下越界」，不是再测一次 Kirk flare。全场平均 CD 合格时，SRAM 拐角或切断端可以已经在 PV-band 外。热点清单是层的合同附件，不是 OPC 工程师的可选海报。</p><h3 id="pv-band-不是-e–d-窗的别名" tabindex="-1">PV-band 不是 E–D 窗的别名 <a class="header-anchor" href="#pv-band-不是-e–d-窗的别名" aria-label="Permalink to &quot;PV-band 不是 E–D 窗的别名&quot;">​</a></h3><p>E–D 窗是选定关键图形的平均 CD 合格面积。PV-band 是同一组过程变化下，轮廓扫出的几何包络（加或不加套刻偏移）。窗大而带厚，说明图形在窗里扭动——电学仍可能死。计算光刻用带厚当目标，FEM 用面积当目标，两张图要一起读。</p><p><span class="marginnote">术语翻译：PV-band（process variation band，工艺变化带）就是把剂量、焦点在允许范围内「扫一圈」，把每个工艺点的轮廓叠在一起得到的一条最宽误差带。带比套刻与电学余量窄，图形才算安全；带厚而窗大，说明图形在窗里乱扭，照样危险。</span></p><p><span class="marginnote">热点检测是在全芯片上找 PV-band 越界的局部，不是只对 FEM 垫上的线栅负责。垫合格、产品死，是选题偏差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模拟：在校准过的光学 + 胶模型上，对全芯片或热区 clips 扫剂量、焦点、可选套刻与掩模误差，输出 EPE / 桥连 / 断线指标。命中的热点回 OPC 或改设计规则。硅片验证用 SEM 审查这些坐标，而不是再平均进 OCD。Flare 模型必须开着，否则开阔区旁边的暗图形会被漏掉——上一课的底座是热点的前置，不是替代。</p><p>过程变化的矩形从产品控制图来：实际剂量 CDU、实际焦指纹、实际套刻，而不是教科书上的 \\(\\pm 10\\%\\) 与 \\(\\pm 50\\,\\mathrm{nm}\\) 随便填。矩形填大了，热点满天飞；填小了，签核通过、硅片失败。</p><p><span class="marginnote">数字实例：若产线实际剂量控制是 ±5%、焦点指纹 ±40 nm，签核时却填教科书矩形 ±10%、±50 nm，会冒出一大批硅片上根本遇不到的假热点，修复资源全浪费；反过来把矩形填小，签核绿灯、硅片翻车。矩形必须抄自己的控制图。</span></p><p>掩模误差（MEEF 大的边）要进带的第三轴，否则热点清单会漏掉掩模厂能修的那一类。</p><h3 id="与随机缺孔的边界" tabindex="-1">与随机缺孔的边界 <a class="header-anchor" href="#与随机缺孔的边界" aria-label="Permalink to &quot;与随机缺孔的边界&quot;">​</a></h3><p>PV-band 是平均轮廓的过程变化。EUV 孔的随机缺失是尾部事件，平均带仍可能「开着」。热点清单要另叠随机感知项，不能用 PV-band 绿色宣言零缺孔。<a href="/litho/stochastic-holes">stochastic-holes</a> 已经分开均值与极值，这里只禁止偷换。</p>',17)),(e(),l(i,null,{default:E(()=>[s(o,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20NOM%5B%22%E5%90%8D%E4%B9%89%E8%BD%AE%E5%BB%93%22%5D%20--%3E%20PV%5B%22%E6%89%AB%20E%20%2F%20z%20%2F%20overlay%22%5D%0A%20%20PV%20--%3E%20BAND%5B%22PV-band%20%E5%8C%85%E7%BB%9C%22%5D%0A%20%20FLARE%5B%22flare%20%E5%BA%95%E5%BA%A7%22%5D%20--%3E%20PV%0A%20%20BAND%20--%3E%20HS%5B%22%E7%83%AD%E7%82%B9%20clips%22%5D%0A%20%20HS%20--%3E%20FIX%5B%22OPC%20%2F%20%E8%AE%BE%E8%AE%A1%E8%A7%84%E5%88%99%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"二维图形的 NILS 在拐角处掉得快，离焦时等高线收缩不对称，线端缩回、拐角变圆，桥连与断开在带的两侧。SRAF 在窗边沿可能打印，成为新热点。Flare 随局部开孔率抬 \\(I_\\mathrm{min}\\)，密区里的孤立暗线与开阔区里的密线，热点清单不同。同一套 OPC 在两块密度上不能当同一张带。",-1)),(e(),l(i,null,{default:E(()=>[s(o,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%BA%E4%BB%80%E4%B9%88%E6%8B%90%E8%A7%92%E5%92%8C%E7%BA%BF%E7%AB%AF%E5%85%88%E5%87%BA%E4%BA%8B%EF%BC%9F%22%5D%20--%3E%20A%5B%22%E4%BA%8C%E7%BB%B4%E6%8B%90%E8%A7%92%EF%BC%9ANILS%20%E6%8E%89%E5%BE%97%E5%BF%AB%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E7%BA%BF%E7%AB%AF%EF%BC%9A%E4%B8%80%E7%AB%AF%E6%97%A0%E9%82%BB%E7%BA%BF%E6%94%AF%E6%92%91%22%5D%0A%20%20A%20--%3E%20C%5B%22%E7%A6%BB%E7%84%A6%E6%97%B6%E8%BD%AE%E5%BB%93%E4%B8%8D%E5%AF%B9%E7%A7%B0%E6%94%B6%E7%BC%A9%22%5D%0A%20%20B%20--%3E%20C%0A%20%20C%20--%3E%20D1%5B%22%E5%B8%A6%E7%9A%84%E4%B8%80%E4%BE%A7%EF%BC%9A%E7%BA%BF%E7%AB%AF%E7%BC%A9%E5%9B%9E%20%E2%86%92%20%E6%96%AD%E5%BC%80%22%5D%0A%20%20C%20--%3E%20D2%5B%22%E5%B8%A6%E7%9A%84%E5%8F%A6%E4%B8%80%E4%BE%A7%EF%BC%9A%E6%8B%90%E8%A7%92%E5%A4%96%E6%B6%A8%20%E2%86%92%20%E6%A1%A5%E8%BF%9E%22%5D%0A%20%20D1%20--%3E%20HS%5B%22PV-band%20%E8%B6%8A%E7%95%8C%E7%83%AD%E7%82%B9%22%5D%0A%20%20D2%20--%3E%20HS%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p>套刻偏移把邻层图形推进带内：通孔相对金属的热点是光刻带与套刻的卷积，不是纯 CD。LELE 的颜色边界更是人为热点源。计算光刻通称把这些叫 process-window limiting patterns，不叫镜头坏了。</p><p><span class="marginnote">常见误区：看到通孔对金属的热点就归罪光刻 CD。实际常是套刻偏移把孔推离了金属端点——这是光刻带与套刻卷出来的失败，再怎么修 CD 都不收敛，要动的是 overlay 或端点外扩。</span></p><p><span class="marginnote">只展示一条密线的 PV-band 变窄，是 SMO/ILT 海报的选题偏差。逻辑后段的二维热点才决定这一层签核。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某次 ILT 案例的带厚改善写成节点良率，也不讨论未公开的全芯片小时数。镜头像差是设计波前，flare 是散射底座，热点是图形在两者之上的局部失败——三个旋钮，修错不收敛。后课默认：计量签核包含热点 SEM，不只是场均值 CDU。</p><p>刻蚀会把 ADI 热点平移或放大成 AEI 热点，下一课才写偏置；本课若用刻蚀后 SEM 验热点，必须声明，不能和 OPC 的显影模型对打。</p><p><span class="marginnote">PV-band 的剂量轴来自产品剂量控制，不是胶衬度曲线的全量程。把 \\(\\gamma\\) 测到的极端剂量填进带，热点会假性爆炸。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>热点是过程变化下先越界的局部图形；PV-band 是轮廓包络。</li><li>与 E–D 窗面积不同：窗大仍可带厚。</li><li>Flare 底座必须进模拟，否则密度相关热点漏检。</li><li>平均带看不见随机缺孔；验证用 SEM 坐标，不用 OCD 均值。</li><li>出处：计算光刻通称（OPC / SMO / ILT 的 PV-band 与 hotspot）；Mack / Levinson 对窗口图形交集的讨论。</li></ul>',9))])}const F=B(d,[["render",h]]);export{f as __pageData,F as default};
